import {SCENARIOS,PLAYERS,position,clock as matchClock} from './engine.js';
import {matchStory} from './match-story.js';
import {PITCHSIDE,pitchsideStory} from './pitchside-story.js';

const $=id=>document.getElementById(id),svgNS='http://www.w3.org/2000/svg';
const params=new URLSearchParams(location.hash.slice(1));
const room=params.get('room'),key=params.get('key');
let base='',cue=null,mode=params.get('mode')||'analyst',producerMode=null,challenged=false,ended=false,sequence=0;
const roles={analyst:['S','SCOUT'],guide:['G','GUIDE'],math:['V','VECTOR'],reviewer:['C','CHECK'],presenter:['H','HOST']};
const validRoom=/^[a-f0-9]{24}$/.test(room||'')&&/^[a-f0-9]{48}$/.test(key||'');

function node(tag,attrs={}){const n=document.createElementNS(svgNS,tag);for(const [k,v] of Object.entries(attrs))n.setAttribute(k,v);return n;}
function demoCue(){const input={source:'match',scenario:'wide',time:18,language:'en',mode:'analyst',focus:7,team:'harbor',corrected:false};const s=matchStory(input);return {schema:'btr.broadcast-cue.v1',sequence:1,source:'match',source_id:'wide',cutoff:18,clock:s.clock,revision:1,language:'en',mode:'analyst',title:s.title,body:s.body,evidence_ids:s.evidence.map(e=>e.id),evidence:s.evidence.slice(-6).map(e=>({id:e.id,type:e.record_type||e.type||'event',second:Number(e.second??e.end??18),description:e.description||e.detail||[e.type,e.outcome].filter(Boolean).join(' · ')||'Recorded source'})),experience:{team:'harbor',focus:7,corrected:false,synthetic:true},explanation:{observation:s.analysis.summary,calculation:s.equation,review:s.review.reason,decision:s.review.decision}};}
function cueInput(overrides={}){if(cue.source==='pitchside')return {source:'pitchside',clip_id:PITCHSIDE.id,time:cue.cutoff,language:cue.language||'en',mode,clipChallenge:challenged,...overrides};return {source:'match',scenario:cue.source_id,time:cue.cutoff,language:cue.language||'en',mode,focus:cue.experience?.focus||7,team:cue.experience?.team||'neutral',corrected:challenged||cue.experience?.corrected===true,...overrides};}
function activeStory(){return cue.source==='pitchside'?pitchsideStory(cueInput()):matchStory(cueInput());}
function scoreText(story){return cue.source==='match'?`${story.brief.score.harbor} — ${story.brief.score.north}`:'0 — 0';}
function renderPitch(){const svg=$('pitch');svg.replaceChildren();svg.append(node('rect',{class:'field',x:1,y:1,width:103,height:66}),node('line',{class:'field',x1:52.5,y1:1,x2:52.5,y2:67}),node('circle',{class:'field',cx:52.5,cy:34,r:9.15}),node('rect',{class:'field',x:1,y:14,width:16.5,height:40}),node('rect',{class:'field',x:87.5,y:14,width:16.5,height:40}),node('circle',{class:'field',cx:52.5,cy:34,r:.8}));
 const scenario=SCENARIOS.find(s=>s.id===(cue.source==='match'?cue.source_id:'wide'))||SCENARIOS[0],t=cue.source==='match'?cue.cutoff:Math.min(36,cue.cutoff*.6),corrected=challenged&&scenario.id==='wide';
 const focus=Number(cue.experience?.focus)||scenario.focus,start=position(scenario,focus,0,corrected),current=position(scenario,focus,t,corrected);svg.append(node('path',{class:'trail',d:`M ${start[0]} ${start[1]} L ${current[0]} ${current[1]}`}));
 for(const p of PLAYERS){const [x,y]=position(scenario,p.id,t,corrected),g=node('g',{class:`player${p.id===focus?' focus':''}`});g.append(node('circle',{cx:x,cy:y,r:p.id===focus?2.25:1.75,fill:p.team==='harbor'?'#ff365d':'#37a4ff'}));const label=node('text',{x,y:y+1.05});label.textContent=String(p.id>100?p.id-100:p.id);g.append(label);svg.append(g);}
 $('focus-toggle').textContent='FOLLOW '+(focus>100?focus-100:focus);$('pitch-caption').textContent=cue.source==='pitchside'?'Film evidence is time-linked; the pitch is a clearly labelled companion illustration.':'Positions, movement trail and sources share the current synthetic cutoff.';
}
function renderSources(story){const records=cue.evidence?.length?cue.evidence:story.evidence.slice(-6).map(e=>({id:e.id,type:e.record_type||e.type||'event',description:e.description||e.detail||'Recorded source'}));$('source-list').replaceChildren(...records.map(r=>{const d=document.createElement('div');d.className='source-row';d.innerHTML=`<b>${escapeText(r.id)} · ${escapeText(String(r.type).toUpperCase())}</b><p>${escapeText(r.description)}</p>`;return d;}));$('evidence-count').textContent=`${records.length} SOURCE${records.length===1?'':'S'}`;
}
function escapeText(value){return String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function render(){if(!cue)return;const story=activeStory();document.documentElement.lang=cue.language||'en';$('score').textContent=scoreText(story);$('clock').textContent=story.clock||cue.clock;$('revision').textContent=`R${story.revision||cue.revision} · SYNTHETIC`;$('moment-kicker').textContent={beginner:'NEW TO FOOTBALL',math:'SHOW THE MATH',analyst:'TACTICAL VIEW',player:'PLAYER FOCUS',fan:'FOR THE FAN'}[mode]||'THE MOMENT';$('moment-title').textContent=story.title||cue.title;$('moment-body').textContent=story.body||cue.body;document.querySelectorAll('.mode-rack button').forEach(b=>b.classList.toggle('selected',b.dataset.mode===mode));
 const observation=story.analysis?.summary||cue.explanation?.observation||story.title,calculation=story.equation||cue.explanation?.calculation||'No calculation is needed for this wording.',review=story.review?.reason||cue.explanation?.review||'The claim is limited to the visible record.';$('proof-observed').textContent=observation;$('proof-source').textContent=`Evidence through ${story.clock||cue.clock} · revision ${story.revision||cue.revision}.`;$('proof-calculated').textContent=calculation;$('proof-interpreted').textContent=story.body||cue.body;$('proof-limit').textContent=review;renderSources(story);renderPitch();
 const connected=validRoom&&!ended;$('connection-pill').classList.toggle('off',!connected);$('connection-pill').querySelector('span').textContent=ended?'SESSION ENDED':connected?'SYNCED LIVE':'DEMO MODE';$('sync-label').textContent=connected?'LIVE WITH THE MAIN SCREEN':'INTERACTIVE DEMO';
}
function applyCue(data){if(data.schema!=='btr.broadcast-cue.v1'||data.sequence<=sequence)return;const sourceChanged=!cue||cue.source!==data.source||cue.source_id!==data.source_id||cue.revision!==data.revision||cue.cutoff!==data.cutoff;if(producerMode===null||data.mode!==producerMode)mode=data.mode||mode;producerMode=data.mode;sequence=data.sequence;cue=data;if(sourceChanged)challenged=false;render();if(navigator.vibrate)navigator.vibrate(18);}
async function connect(){if(!validRoom){cue=demoCue();render();return;}while(!ended){try{const r=await fetch(base+`/api/broadcast/${room}/stream`,{headers:{Authorization:'Bearer '+key}});if(!r.ok){if([403,410].includes(r.status))ended=true;throw Error('Session unavailable');}const reader=r.body.getReader(),decoder=new TextDecoder();let buffer='';while(!ended){const {done,value}=await reader.read();if(done)break;buffer+=decoder.decode(value,{stream:true});if(buffer.length>256000)throw Error('Stream too large');let at;while((at=buffer.indexOf('\n\n'))>=0){const block=buffer.slice(0,at);buffer=buffer.slice(at+2);const type=block.split('\n').find(x=>x.startsWith('event:'))?.slice(6).trim(),raw=block.split('\n').filter(x=>x.startsWith('data:')).map(x=>x.slice(5)).join('');if(!raw)continue;const data=JSON.parse(raw);if(type==='cue')applyCue(data);if(type==='stopped')ended=true;}}}catch{}if(!ended)await new Promise(r=>setTimeout(r,1800));}render();}
function toast(text){$('toast').textContent=text;$('toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').hidden=true,2800);}
function addCrew(role,data,draft=false){const [initial,label]=roles[role]||['·',role.toUpperCase()],line=document.createElement('div');line.className='crew-line';line.dataset.role=role;line.innerHTML=`<span class="crew-avatar">${initial}</span><div class="crew-copy"><b>${label}${draft?' · THINKING':''}</b><p>${escapeText(data.summary||data.text||data.delta||'Reviewing the evidence…')}</p><small>${data.evidence_ids?.length?data.evidence_ids.join(' · '):`EVIDENCE THROUGH ${cue.clock}`}</small></div>`;const old=$('crew-stream').querySelector(`[data-role="${role}"]`);old?.remove();$('crew-stream').append(line);$('crew-stream').scrollTop=$('crew-stream').scrollHeight;}
async function ask(question){if(!question||!cue)return;$('crew-stream').replaceChildren();$('send').disabled=true;$('question').disabled=true;try{const endpoint=cue.source==='pitchside'?'/api/clip-desk':'/api/match-desk',r=await fetch(base+endpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(cueInput({question})),signal:AbortSignal.timeout(35000)});if(!r.ok)throw Error((await r.json()).error||'The crew is unavailable.');const reader=r.body.getReader(),decoder=new TextDecoder();let buffer='';while(true){const {done,value}=await reader.read();if(done)break;buffer+=decoder.decode(value,{stream:true});let at;while((at=buffer.indexOf('\n\n'))>=0){const block=buffer.slice(0,at);buffer=buffer.slice(at+2);const type=block.split('\n').find(l=>l.startsWith('event:'))?.slice(6).trim(),raw=block.split('\n').filter(l=>l.startsWith('data:')).map(l=>l.slice(5)).join('');if(!raw)continue;const data=JSON.parse(raw);if(type==='error')throw Error(data.message);if(type==='draft'||type==='post')addCrew(data.role,data,type==='draft');}}}catch(error){$('crew-stream').innerHTML=`<p class="ask-empty">${escapeText(error.message)} The current reviewed explanation remains available above.</p>`;}finally{$('send').disabled=false;$('question').disabled=false;$('question').focus();}}

document.querySelectorAll('.mode-rack button').forEach(button=>button.onclick=()=>{mode=button.dataset.mode;render();if(navigator.vibrate)navigator.vibrate(10);});
$('why').onclick=()=>{$('proof-sheet').hidden=false;$('proof-sheet').scrollIntoView({behavior:'smooth',block:'start'});};$('close-proof').onclick=()=>$('proof-sheet').hidden=true;
$('challenge').onclick=()=>{challenged=!challenged;$('challenge').classList.toggle('active',challenged);$('challenge').firstChild.textContent=challenged?'RESTORE RECORDED EVIDENCE ':'CHANGE THE EVIDENCE ';const result=$('change-result');result.hidden=!challenged;if(challenged){const meaningful=cue.source==='match'&&cue.source_id==='wide'&&cue.cutoff>=16;result.innerHTML=meaningful?'<b>SIMULATION · CLAIM WITHDRAWN</b>The defender now holds position. The run and completed passes remain recorded, but the claim that the run moved the defender no longer survives.':'<b>SIMULATION · LIMIT ADDED</b>The changed assumption is separated from the recorded play. Any tactical conclusion depending on it must be withheld.';}render();};
$('ask-form').onsubmit=e=>{e.preventDefault();const q=$('question').value.trim();if(q){$('question').value='';ask(q);}};document.querySelectorAll('.quick-asks button').forEach(b=>b.onclick=()=>ask(b.textContent));
$('voice').onclick=()=>{const SpeechRecognition=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SpeechRecognition){toast('Voice input is not available in this browser.');return;}const r=new SpeechRecognition();r.lang={en:'en-US',es:'es-ES',pt:'pt-BR'}[cue?.language]||'en-US';r.interimResults=false;$('voice').textContent='●';r.onresult=e=>{$('question').value=e.results[0][0].transcript;$('question').focus();};r.onerror=()=>toast('I could not hear that. Try typing your question.');r.onend=()=>$('voice').textContent='⌁';r.start();};
document.querySelectorAll('.dock button').forEach(b=>b.onclick=()=>{document.querySelectorAll('.dock button').forEach(x=>x.classList.toggle('active',x===b));const target=b.dataset.scroll==='top'?document.body:$(b.dataset.scroll);target.scrollIntoView({behavior:'smooth',block:'start'});});
$('focus-toggle').onclick=()=>toast('Player focus follows the selected player from the main screen.');

fetch('api-config.json').then(r=>r.json()).then(c=>{base=c.baseUrl||'';return connect();}).catch(()=>{cue=demoCue();render();});
